/**
 * Create an original four-image set for each Cave Divers catalogue record.
 *
 * Every image is generated by gpt-image-1.5, uploaded to the Cave Divers
 * Cloudinary folder, then persisted with an exact tenant-and-current-images
 * compare-and-set. The script is resumable: a retry starts after the last
 * successfully persisted image and never imports a source or competitor asset.
 *
 * Dry run (no database, image API, or Cloudinary connection):
 *   npm run images:cave-divers
 * Apply in the backend service environment:
 *   npm run images:cave-divers -- --apply --confirm-tenant=cave-divers --confirm-assets=generated-only
 */

import { connectDatabase, disconnectDatabase } from '../config/database';
import { Attraction } from '../models/Attraction';
import { Tenant } from '../models/Tenant';
import { generateImageFromPrompt } from '../services/image-generation.service';
import { uploadBase64Image } from '../services/upload.service';

const TENANT_SLUG = 'cave-divers';
const IMAGE_FOLDER = 'tours/cave-divers';
const IMAGE_URL_MARKER = '/attractions-network/tours/cave-divers/';
const IMAGES_PER_TOUR = 4;

const STYLE = [
  'Original photorealistic editorial travel photograph of a generic Red Sea experience in Hurghada, Egypt.',
  'Premium natural-light photography, believable people and equipment, vivid but realistic underwater colour, wide landscape composition.',
  'Do not depict or reproduce a real dive centre, employee, instructor, customer, logo, named vessel, uniform, or identifiable brand.',
  'Do not imitate any source-site or marketplace photograph.',
  'No text, no legible signage, no logos, no watermark, no collage, no split panels.',
].join(' ');

export interface CaveDiversImagePlanItem {
  slug: string;
  scenes: readonly [string, string, string, string];
}

