export function validateCaveDiversImagePlan(): string[] {
  const errors: string[] = [];
  if (CAVE_DIVERS_IMAGE_PLAN.length !== 7) errors.push('The image plan must target exactly seven catalogue records.');
  const slugs = new Set<string>();
  for (const item of CAVE_DIVERS_IMAGE_PLAN) {
    if (slugs.has(item.slug)) errors.push(`Duplicate image target: ${item.slug}`);
    slugs.add(item.slug);
    if (item.scenes.length !== IMAGES_PER_TOUR) errors.push(`Expected four scenes for ${item.slug}.`);
    for (const scene of item.scenes) {
      if (scene.trim().length < 80) errors.push(`Scene is too thin for ${item.slug}.`);
    }
  }
  if (!/no text/i.test(STYLE) || !/no logos/i.test(STYLE) || !/do not imitate/i.test(STYLE)) {
    errors.push('The generated-only and no-brand prompt guard is missing.');
  }
  return errors;
}

const fullPrompt = (scene: string): string => `${scene} ${STYLE}`;

async function applyImagePlan(): Promise<void> {
  const args = new Set(process.argv.slice(2));
  if (!args.has(`--confirm-tenant=${TENANT_SLUG}`) || !args.has('--confirm-assets=generated-only')) {
    throw new Error(
      `Apply fence missing. Pass --confirm-tenant=${TENANT_SLUG} and --confirm-assets=generated-only.`,
    );
  }

  await connectDatabase();
  try {
    const tenant = await Tenant.findOne({ slug: TENANT_SLUG }).select('_id slug status heroImages');
    if (!tenant || tenant.status !== 'active') throw new Error('The active Cave Divers tenant was not found.');

    const targetSlugs = CAVE_DIVERS_IMAGE_PLAN.map((item) => item.slug);
    const tours = await Attraction.find({ slug: { $in: targetSlugs } })
      .select('_id slug status enquiryOnly ownerTenantId tenantIds images');
    if (tours.length !== targetSlugs.length) {
      const found = new Set(tours.map((tour) => tour.slug));
      throw new Error(`Missing catalogue records: ${targetSlugs.filter((slug) => !found.has(slug)).join(', ')}`);
    }

    for (const tour of tours) {
      const owned = String(tour.ownerTenantId) === String(tenant._id)
        && tour.tenantIds.some((tenantId) => String(tenantId) === String(tenant._id));
      if (!owned || tour.status !== 'active' || tour.enquiryOnly !== true) {
        throw new Error(`Refusing image write outside the Cave Divers enquiry-only catalogue: ${tour.slug}.`);
      }
      if ((tour.images || []).some((url) => !url.includes(IMAGE_URL_MARKER))) {
        throw new Error(`Refusing to replace non-Cave imagery already present on ${tour.slug}.`);
      }
      if ((tour.images || []).length > IMAGES_PER_TOUR) {
        throw new Error(`Refusing to trim an expanded gallery on ${tour.slug}.`);
      }
    }

    console.log(JSON.stringify({
      mode: 'pre-apply-report',
      tenant: TENANT_SLUG,
      targets: CAVE_DIVERS_IMAGE_PLAN.map((item) => {
        const tour = tours.find((candidate) => candidate.slug === item.slug)!;
        return { slug: item.slug, existing: tour.images.length, remaining: IMAGES_PER_TOUR - tour.images.length };
      }),
    }, null, 2));

    for (const item of CAVE_DIVERS_IMAGE_PLAN) {
      const tour = tours.find((candidate) => candidate.slug === item.slug)!;
      let currentImages = [...(tour.images || [])];
      for (let index = currentImages.length; index < IMAGES_PER_TOUR; index += 1) {
        const { base64, mimeType } = await generateImageFromPrompt({
          prompt: fullPrompt(item.scenes[index]),
          size: '1536x1024',
          quality: 'high',
          outputFormat: 'jpeg',
        });
        const uploaded = await uploadBase64Image(
          `data:${mimeType};base64,${base64}`,
          IMAGE_FOLDER,
          { publicId: `${item.slug}-${String(index + 1).padStart(2, '0')}`, overwrite: true },
        );
        if (!uploaded.url.includes(IMAGE_URL_MARKER)) {
          throw new Error(`Upload returned an unexpected asset path for ${item.slug}.`);
        }
        const nextImages = [...currentImages, uploaded.url];
        const result = await Attraction.updateOne(
          {
            _id: tour._id,
            ownerTenantId: tenant._id,
            enquiryOnly: true,
            images: currentImages,
          },
          { $set: { images: nextImages } },
        );
        if (result.modifiedCount !== 1) {
          throw new Error(`Concurrent image edit detected on ${item.slug}; uploaded asset was not attached.`);
        }
        currentImages = nextImages;
        console.log(JSON.stringify({ slug: item.slug, image: index + 1, url: uploaded.url }));
      }
    }

    const refreshed = await Attraction.find({ slug: { $in: targetSlugs }, ownerTenantId: tenant._id })
      .select('slug images');
    const heroSlugs = [
      'cave-divers-red-sea-daily-diving',
      'cave-divers-discover-scuba-diving',
      'cave-divers-dolphin-house-sea-trip',
      'cave-divers-orange-bay-giftun-island',
    ];
    const heroImages = heroSlugs.map((slug) => {
      const image = refreshed.find((tour) => tour.slug === slug)?.images?.[0];
      if (!image) throw new Error(`Hero source image is missing for ${slug}.`);
      return image;
    });
    const currentHeroImages = [...(tenant.heroImages || [])];
    if (currentHeroImages.some((url) => !url.includes(IMAGE_URL_MARKER))) {
      throw new Error('Refusing to replace tenant hero imagery not created by this pipeline.');
    }
    if (JSON.stringify(currentHeroImages) !== JSON.stringify(heroImages)) {
      const result = await Tenant.updateOne(
        { _id: tenant._id, slug: TENANT_SLUG, heroImages: currentHeroImages },
        { $set: { heroImages } },
      );
      if (result.modifiedCount !== 1) throw new Error('Concurrent tenant hero edit detected; no hero array was replaced.');
    }

    const invalid = refreshed.filter((tour) => (
      tour.images.length !== IMAGES_PER_TOUR
      || tour.images.some((url) => !url.includes(IMAGE_URL_MARKER))
    ));
    if (invalid.length) throw new Error(`Post-apply image verification failed: ${invalid.map((tour) => tour.slug).join(', ')}`);
    console.log(JSON.stringify({
      mode: 'applied',
      generatedOnly: true,
      tours: refreshed.length,
      images: refreshed.reduce((sum, tour) => sum + tour.images.length, 0),
      tenantHeroes: heroImages.length,
    }, null, 2));
  } finally {
    await disconnectDatabase();
  }
}

export async function main(): Promise<void> {
  const errors = validateCaveDiversImagePlan();
  if (errors.length) throw new Error(`Image plan is invalid:\n- ${errors.join('\n- ')}`);
  if (!new Set(process.argv.slice(2)).has('--apply')) {
    console.log(JSON.stringify({
      mode: 'dry-run',
      tenant: TENANT_SLUG,
      generatedOnly: true,
      folder: `attractions-network/${IMAGE_FOLDER}`,
      targets: CAVE_DIVERS_IMAGE_PLAN.map((item) => ({ slug: item.slug, images: item.scenes.length })),
      safeguards: ['no database connection', 'no image generation', 'no upload', 'no source or competitor imagery'],
    }, null, 2));
    return;
  }
  await applyImagePlan();
}

if (require.main === module) {
  main().catch((error) => {
    console.error(`[cave-divers-images] ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  });
}
